lor:#fecdca;background:#fef3f2;color:#b42318}.mobile-toggle{display:none;border:0;background:#fff;font-size:22px}.mobile-overlay{display:none}@media(max-width:1024px){:root{--sidebar:240px}.stat{grid-column:span 6}.span-8,.span-4{grid-column:span 12}}@media(max-width:760px){.admin-sidebar{transform:translateX(-100%);transition:.2s}.admin-sidebar.open{transform:translateX(0)}.main{margin-left:0}.topbar{padding:0 16px}.mobile-toggle{display:block}.content{padding:20px 15px}.stat{grid-column:span 12}.form-grid{grid-template-columns:1fr}.mobile-overlay{position:fixed;inset:0;background:rgba(16,24,40,.35);z-index:40}.mobile-overlay.open{display:block}}
